// Which glasses the stage is drawn as. Same frames, same contract, two
// looks: the Even G2's green monochrome projection, or the Meta Ray-Ban
// Display's white cards (Alexis, 2026-09-05, from a reference still). A URL
// param, then a remembered choice, then Even — the device we build for first
// (D-228).

export type Device = 'even' | 'meta'

export const DEVICE_NAME: Record<Device, string> = {
  even: 'Even G2',
  meta: 'Meta Ray-Ban Display',
}

export function resolveDevice(): Device {
  const fromUrl = new URLSearchParams(location.search).get('device')
  if (fromUrl === 'even' || fromUrl === 'meta') {
    try { localStorage.setItem('tp.device', fromUrl) } catch { /* private mode */ }
    return fromUrl
  }
  try {
    return localStorage.getItem('tp.device') === 'meta' ? 'meta' : 'even'
  } catch {
    return 'even'
  }
}

/** Markup for the two-pill switch. Bind it with `bindDeviceToggles`. */
export function deviceToggleHtml(current: Device, label?: string): string {
  const pill = (d: Device) =>
    `<button type="button" class="device" data-device="${d}" aria-pressed="${d === current}">${DEVICE_NAME[d]}</button>`
  return `<div class="devices" role="group"${label ? ` aria-label="${label}"` : ''}>${label ? `<span class="devices-label">${label}</span>` : ''}${pill('even')}${pill('meta')}</div>`
}

/**
 * Applies `current` to the stage root (`.meta` class), wires every toggle
 * under `root`, and keeps them in sync. `onChange` fires after the class flips.
 */
export function bindDeviceToggles(root: HTMLElement, current: Device, onChange?: (d: Device) => void): void {
  const apply = (d: Device) => {
    root.classList.toggle('meta', d === 'meta')
    for (const b of root.querySelectorAll<HTMLButtonElement>('.device')) {
      b.setAttribute('aria-pressed', String(b.dataset.device === d))
    }
    try { localStorage.setItem('tp.device', d) } catch { /* private mode */ }
    onChange?.(d)
  }
  apply(current)
  root.addEventListener('click', (ev) => {
    const b = (ev.target as HTMLElement).closest<HTMLButtonElement>('.device')
    if (!b) return
    const d = b.dataset.device
    if (d === 'even' || d === 'meta') apply(d)
  })
}
