// The TalkPilot ping. One sound for a steer and a cue — the SFX Alexis has
// been using in content (public/sfx/ping.mp3, 2026-09-05) — so what the film
// plays is what the brand already sounds like. If the file can't load, the
// earlier Web Audio tone stands in so a landing never goes silent. Browsers
// refuse sound without a gesture, hence `unlock()`.

export interface Earcon {
  unlock(): Promise<void>
  play(kind: 'steer' | 'cue'): void
}

const PING_URL = `${import.meta.env.BASE_URL}sfx/ping.mp3`

/** Play-and-pause a media element inside a gesture so iOS lets it play later. */
export function warm(a: HTMLAudioElement): void {
  const wasMuted = a.muted
  a.muted = true
  const p = a.play()
  if (p && typeof p.then === 'function') {
    p.then(() => {
      a.pause()
      a.currentTime = 0
      a.muted = wasMuted
    }).catch(() => {
      a.muted = wasMuted
    })
  } else {
    a.muted = wasMuted
  }
}

export function createEarcon(): Earcon {
  let ctx: AudioContext | null = null
  let ping: HTMLAudioElement | null = null
  let pingOk = false

  const synth = (kind: 'steer' | 'cue') => {
    if (!ctx) return
    const t = ctx.currentTime
    const notes = kind === 'steer' ? [880, 1174.66] : [659.25]
    notes.forEach((freq, i) => {
      const at = t + i * 0.11
      const osc = ctx!.createOscillator()
      const gain = ctx!.createGain()
      osc.type = 'sine'
      osc.frequency.value = freq
      gain.gain.setValueAtTime(0.0001, at)
      gain.gain.exponentialRampToValueAtTime(0.06, at + 0.015)
      gain.gain.exponentialRampToValueAtTime(0.0001, at + 0.17)
      osc.connect(gain).connect(ctx!.destination)
      osc.start(at)
      osc.stop(at + 0.19)
    })
  }

  return {
    async unlock() {
      if (!ping) {
        ping = new Audio(PING_URL)
        ping.preload = 'auto'
        ping.volume = 0.7
        ping.addEventListener('canplaythrough', () => { pingOk = true }, { once: true })
        ping.addEventListener('error', () => { pingOk = false })
        ping.load()
        // iOS Safari lets a media element play later only if it has played
        // once inside a user gesture. Do that now, silently, synchronously.
        warm(ping)
      }
      if (!ctx) {
        try {
          ctx = new AudioContext()
        } catch {
          ctx = null
        }
      }
      await ctx?.resume().catch(() => undefined)
    },
    play(kind) {
      if (ping && (pingOk || ping.readyState >= 3)) {
        ping.currentTime = 0
        ping.play().catch(() => synth(kind))
        return
      }
      synth(kind)
    },
  }
}
